import java.util.Scanner;

class ATMException extends Exception {
    public ATMException(String message) {
        super(message);
    }
}

class InvalidPINException extends ATMException {
    public InvalidPINException() {
        super("Invalid PIN!");
    }
}

class InsufficientBalanceException extends ATMException {
    public InsufficientBalanceException() {
        super("Insufficient balance!");
    }
}

class ATM {
    private static final int CORRECT_PIN = 1234;
    private static final int INITIAL_BALANCE = 10000;
    private int balance = INITIAL_BALANCE;
    private int pin = CORRECT_PIN;

    public void validatePin(int inputPin) throws InvalidPINException {
        if (inputPin != pin) {
            throw new InvalidPINException();
        }
    }

    public void withdraw(int amount) throws InsufficientBalanceException {
        if (amount > balance) {
            throw new InsufficientBalanceException();
        }
        balance -= amount;
    }

    public int getBalance() {
        return balance;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int pin;
        try {
            String pinLine = sc.nextLine().trim();
            pin = Integer.parseInt(pinLine);
        } catch (NumberFormatException e) {
            System.out.println("Invalid PIN!");
            return;
        }

        String amountLine;
        try {
            amountLine = sc.nextLine().trim();
        } catch (Exception e) {
            System.out.println("Invalid PIN!");
            return;
        }

        int amount;
        try {
            amount = Integer.parseInt(amountLine);
        } catch (NumberFormatException e) {
            System.out.println("Invalid PIN!");
            return;
        }

        if (amount < 0) {
            amount = -amount;
        }

        ATM atm = new ATM();

        try {
            atm.validatePin(pin);
        } catch (InvalidPINException e) {
            System.out.println("Invalid PIN!");
            return;
        }

        try {
            atm.withdraw(amount);
            System.out.println(atm.getBalance());
        } catch (InsufficientBalanceException e) {
            System.out.println("Insufficient balance!");
        }
    }
}
